  const auto& begin=program.identity.at("begin");const auto& binding=program.identity.at("native_binding");
  p::need(binding.at("epoch_id")==begin.at("epoch_id")&&binding.at("epoch_launch_ordinal")==begin.at("epoch_launch_ordinal")&&binding.at("sampler_source_launch_key")==begin.at("source_launch_key"),"synthetic native launch-key shape binding");
  limits.max_live_nodes=5000000;
